	}
	tick := m.spinnerTickIfIdle()
	for _, ref := range refs {
		m.remediation.scanning[ref] = true
	}
	m.refreshRemediation()

	timeout := time.Duration(m.config.Scan.Timeout) * time.Second
	if timeout <= 0 {
